package net.minecraft.client.player;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.*;import net.minecraft.world.phys.*;import java.util.function.Supplier;public class LocalPlayer extends Player implements com.tacz.guns.api.client.gameplay.IClientPlayerGunOperator{public boolean spectator,range=true,ads;public int swings,aimCalls;public ItemStack off=new ItemStack(new Item());public final me.xjqsh.lrtactical.capability.CombatProperties combat=new me.xjqsh.lrtactical.capability.CombatProperties();public boolean isSpectator(){return spectator;}public Vec3 getEyePosition(){return Vec3.ZERO;}public Vec3 getLookAngle(){return new Vec3(1,0,0);}public boolean canInteractWithBlock(Object pos,double offset){return range;}public boolean canInteractWithEntity(Object e,double offset){return range;}public ItemStack getItemInHand(InteractionHand h){return h==InteractionHand.MAIN_HAND?main:off;}public void swing(InteractionHand hand){swings++;}public boolean isAim(){return ads;}public void aim(boolean value){ads=value;aimCalls++;}public Object getData(Supplier<?> supplier){return combat;}}
